# Pure-Python arithmetic checks are author checks, not independent verification.
def mm(A,B): return [[sum(a*b for a,b in zip(row,col)) for col in zip(*B)] for row in A]
def mv(A,v): return [sum(a*b for a,b in zip(row,v)) for row in A]
def tr(A): return [list(x) for x in zip(*A)]
def add(a,b): return [x+y for x,y in zip(a,b)]
def rx(t):
 c,s=math.cos(t),math.sin(t);return [[1,0,0],[0,c,-s],[0,s,c]]
def ry(t):
 c,s=math.cos(t),math.sin(t);return [[c,0,s],[0,1,0],[-s,0,c]]
def rz(t):
 c,s=math.cos(t),math.sin(t);return [[c,-s,0],[s,c,0],[0,0,1]]
def hom(R,p):return [row+[v] for row,v in zip(R,p)]+[[0,0,0,1]]
def near(a,b,tol=1e-9):
 if isinstance(a,(list,tuple)):return len(a)==len(b) and all(near(x,y,tol) for x,y in zip(a,b))
 return abs(a-b)<=tol
CHECKS=[]
def check(name,actual,expected,tol=1e-9):
 ok=near(actual,expected,tol);CHECKS.append({'id':name,'passed':ok,'actual':actual,'expected':expected,'tolerance':tol,'kind':'author_computation_not_independent_review'});assert ok,(name,actual,expected)
pi=math.pi;I3=[[1,0,0],[0,1,0],[0,0,1]];I4=hom(I3,[0,0,0])
check('quarter_x_on_y',mv(rx(pi/2),[0,1,0]),[0,0,1])
check('quarter_y_on_x',mv(ry(pi/2),[1,0,0]),[0,0,-1])
check('quarter_z_point',mv(rz(pi/2),[2,-1,5]),[1,2,5])
check('rx_ry_product',mm(rx(pi/2),ry(pi/2)),[[0,0,1],[1,0,0],[0,1,0]])
check('ry_rx_product',mm(ry(pi/2),rx(pi/2)),[[0,1,0],[0,0,-1],[-1,0,0]])
check('aligned_translation',add([1,3,2],[4,-2,1]),[5,1,3])
check('general_mapping',add(mv(rz(pi/2),[1,0,0]),[2,0,0]),[2,1,0])
check('composed_translation', [r[3] for r in mm(hom(rz(pi/2),[1,0,0]),hom(I3,[2,0,0]))][:3],[1,2,0])
check('inverse_translation',[-v for v in mv(tr(rz(pi/2)),[2,3,0])],[-3,2,0])
check('worked_example',add(mv(rz(pi/6),[3,7,0]),[10,5,0]),[9.098076211353316,12.562177826491071,0])
check('worked_inverse_origin',[-v for v in mv(tr(rz(pi/6)),[10,5,0])],[-11.160254037844387,0.6698729810778055,0])
check('worked_wrong_rotate_offset_distractor',mv(rz(pi/6),[13,12,0]),[5.258330249197703,16.892304845413264,0])
check('rounded_rotation_squared_norm',.866**2+.5**2,.999956)
check('rotation_animation_step', (pi/2)/39,pi/78)
check('translation_animation_step',1/49,1/(50-1))
R2=mm(ry(pi/6),rx(pi/4));Rfixed=mm(rz(pi/3),R2)
check('fixed_intermediate_x',mv(R2,[1,0,0]),[math.sqrt(3)/2,0,-.5])
check('fixed_final_matrix',Rfixed,[[.43301270,-.43559574,.78914913],[.75,.65973961,-.04736717],[-.5,.61237244,.61237244]],1e-8)
check('fixed_final_r23',Rfixed[1][2],(math.sqrt(6)-2*math.sqrt(2))/8)
check('intrinsic_intermediate_y',mv(mm(rz(pi/3),ry(pi/6)),[0,1,0]),[-math.sqrt(3)/2,.5,0])
check('matched_intrinsic_fixed',mm(mm(rz(pi/3),ry(pi/6)),rx(pi/4)),Rfixed)
check('pitch_recovery',math.degrees(math.atan2(.5,math.sqrt((math.sqrt(3)/4)**2+.75**2))),30)
check('quadrant_yaw',math.degrees(math.atan2(math.sqrt(3)/2,-.5)),120)
check('negative_roll',math.degrees(math.atan2(-1/math.sqrt(2),1/math.sqrt(2))),-45)
for i,(a,b,g) in enumerate([(0,0,0),(.3,-.7,1.1),(-1.2,.4,-.9),(pi/3,pi/6,pi/4),(1.1,pi/2,-.4)]):
 ca,sa,cb,sb,cg,sg=math.cos(a),math.sin(a),math.cos(b),math.sin(b),math.cos(g),math.sin(g)
 expanded=[[ca*cb,ca*sb*sg-sa*cg,ca*sb*cg+sa*sg],[sa*cb,sa*sb*sg+ca*cg,sa*sb*cg-ca*sg],[-sb,cb*sg,cb*cg]]
 R=mm(mm(rz(a),ry(b)),rx(g))
 check(f'all_nine_expansion_case_{i}',R,expanded)
 check(f'orthonormal_case_{i}',mm(tr(R),R),I3)
 T=hom(R,[2,-3,4]);Ti=hom(tr(R),[-x for x in mv(tr(R),[2,-3,4])])
 check(f'rigid_inverse_case_{i}',mm(Ti,T),I4)
 if abs(cb)>1e-6:
  br=math.atan2(-R[2][0],math.hypot(R[0][0],R[1][0]));ar=math.atan2(R[1][0]/math.cos(br),R[0][0]/math.cos(br));gr=math.atan2(R[2][1]/math.cos(br),R[2][2]/math.cos(br))
  check(f'angle_recovery_roundtrip_case_{i}',mm(mm(rz(ar),ry(br)),rx(gr)),R)
check('gimbal_equivalent_yaw_roll',mm(mm(rz(.8),ry(pi/2)),rx(.2)),mm(mm(rz(1.1),ry(pi/2)),rx(.5)))
# Independently permute opaque IDs as well as display order: blind review must not
# reveal an answer through a construction-time option-ID pattern.
for q in Q:
 old_ids=[f'o{i}' for i in range(1,5)];new_ids=old_ids[:]
 random.Random('option-identities:'+q['id']).shuffle(new_ids)
 mapping=dict(zip(old_ids,new_ids))
 for option in q['options']:option['id']=mapping[option['id']]
